<?php
session_start();require_once "../config.php";require_once "../includes/functions.php";require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$title=trim($_POST['title']??'');$author=trim($_POST['author']??'');$category=trim($_POST['category']??'General');$price=max(0,(float)($_POST['price']??0));$stock=max(0,(int)($_POST['stock']??0));
 if($title&&$author){$pdo->prepare("INSERT INTO books(title,author,category,price,stock) VALUES(?,?,?,?,?)")->execute([$title,$author,$category,$price,$stock]);}
 if(isset($_POST['update_id'])){$pdo->prepare("UPDATE books SET price=?,stock=? WHERE id=?")->execute([max(0,(float)$_POST['edit_price']),max(0,(int)$_POST['edit_stock']),(int)$_POST['update_id']]);}
}
$books=$pdo->query("SELECT * FROM books ORDER BY id DESC")->fetchAll();$pageTitle="Admin Dashboard";require "../includes/header.php";?>
<h2>Admin Dashboard - Inventory</h2><form method="post" class="row g-2 mb-4"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><div class="col"><input class="form-control" name="title" placeholder="Title" required></div><div class="col"><input class="form-control" name="author" placeholder="Author" required></div><div class="col"><input class="form-control" name="category" placeholder="Category"></div><div class="col"><input class="form-control" name="price" type="number" step=".01" placeholder="Price" required></div><div class="col"><input class="form-control" name="stock" type="number" placeholder="Stock" required></div><div class="col"><button class="btn btn-primary">Add book</button></div></form>
<table class="table"><tr><th>Book</th><th>Price</th><th>Stock</th><th>Update</th></tr><?php foreach($books as $b): ?><tr><td><?= e($b['title']) ?></td><td><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="update_id" value="<?= (int)$b['id'] ?>"><input class="form-control" name="edit_price" type="number" step=".01" value="<?= e($b['price']) ?>"><input class="form-control" name="edit_stock" type="number" value="<?= (int)$b['stock'] ?>"><button class="btn btn-sm btn-success">Save</button></form></td><td><?= (int)$b['stock'] ?></td><td>Use fields to update</td></tr><?php endforeach; ?></table>
